// Some portions generated by Codex

package org.eclipse.rdf4j.query.algebra;

import static org.assertj.core.api.Assertions.assertThat;

import org.junit.jupiter.api.Test;

class ExtensionElemAnonymousTargetTest {
	@Test
	void anonymousTargetMarkerIsClonedButDoesNotAffectEquality() {
		ExtensionElem unmarked = new ExtensionElem(Var.of("value"), "value");
		assertThat(unmarked.isAnonymousTarget()).isFalse();

		ExtensionElem marked = unmarked.clone();
		assertThat(marked.isAnonymousTarget()).isFalse();
		marked.setAnonymousTarget(true);

		assertThat(marked.isAnonymousTarget()).isTrue();
		assertThat(unmarked.isAnonymousTarget()).isFalse();
		assertThat(marked).isEqualTo(unmarked);
		assertThat(marked.hashCode()).isEqualTo(unmarked.hashCode());

		ExtensionElem markedClone = marked.clone();
		assertThat(markedClone.isAnonymousTarget()).isTrue();
		assertThat(markedClone).isEqualTo(marked);
		assertThat(markedClone.hashCode()).isEqualTo(marked.hashCode());

		markedClone.setAnonymousTarget(false);
		assertThat(markedClone.isAnonymousTarget()).isFalse();
		assertThat(marked.isAnonymousTarget()).isTrue();
	}
}
